tree = {
    'value': 8,
    'left': {'value': 3, 'left': None, 'right': None},
    'right': {'value': 10, 'left': None, 'right': None}
}
target = 10
node = tree
found = False
while node is not None:
    if node['value'] == target:
        found = True
        break
    if target < node['value']:
        node = node['left']
    else:
        node = node['right']
print(found)

